<script setup lang="ts">
import{onBeforeUnmount,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{getRequirement}from'@/api/requirements';import{startEditing,editingHeartbeat,endEditing}from'@/api/editing';import StatusTag from'@/components/StatusTag.vue';const route=useRoute();const item=ref<any>();let timer:any;const id=Number(route.params.id);onMounted(async()=>{item.value=await getRequirement(id);const r=await startEditing('REQUIREMENT',id);if(r.existing_editor) console.info('existing editor',r.existing_editor);timer=setInterval(()=>editingHeartbeat('REQUIREMENT',id),120000)});onBeforeUnmount(()=>{clearInterval(timer);endEditing('REQUIREMENT',id)})
</script>
<template><div class="page" v-if="item"><div class="page-title">{{item.requirement_no}} {{item.title}}</div><el-card><StatusTag :status="item.status"/><el-descriptions :column="1" border style="margin-top:14px"><el-descriptions-item label="优先级">{{item.priority}}</el-descriptions-item><el-descriptions-item label="来源">{{item.source}}</el-descriptions-item><el-descriptions-item label="当前版本">{{item.current_version_id||'-'}}</el-descriptions-item><el-descriptions-item label="需求描述">{{item.description}}</el-descriptions-item><el-descriptions-item label="验收标准">{{item.acceptance_criteria||'-'}}</el-descriptions-item></el-descriptions></el-card></div></template>
